insert into public.misconceptions (id, label, description, insight) values ('m-senilai-tambah', 'Membuat pecahan senilai dengan menambah', 'Menambah (atau mengurangi) bilangan yang sama pada pembilang dan penyebut, bukan mengalikan atau membaginya.', 'Pada beberapa soal pecahan senilai, pilihan jawaban menunjukkan bahwa pecahan senilai masih dibentuk dengan menambah bilangan yang sama pada pembilang dan penyebut. Bagian ini sebaiknya diperkuat dengan kembali ke gambar dan perkalian.') on conflict (id) do update set label = excluded.label, description = excluded.description, insight = excluded.insight;
insert into public.misconceptions (id, label, description, insight) values ('m-penyebut-besar', 'Penyebut lebih besar dianggap bernilai lebih besar', 'Menentukan pecahan yang lebih besar hanya berdasarkan besar penyebutnya.', 'Pada beberapa soal perbandingan pecahan, pilihan jawaban menunjukkan bahwa nilai pecahan masih ditentukan dari besar penyebutnya saja. Perbandingan pecahan masih perlu diperkuat.') on conflict (id) do update set label = excluded.label, description = excluded.description, insight = excluded.insight;
insert into public.misconceptions (id, label, description, insight) values ('m-pembilang-saja', 'Membandingkan hanya lewat pembilang', 'Membandingkan dua pecahan hanya dengan melihat pembilangnya.', 'Pada beberapa soal, pilihan jawaban menunjukkan bahwa pecahan masih dibandingkan hanya dari pembilangnya. Menyamakan penyebut lebih dahulu perlu lebih sering dilatih.') on conflict (id) do update set label = excluded.label, description = excluded.description, insight = excluded.insight;
insert into public.misconceptions (id, label, description, insight) values ('m-jumlah-penyebut', 'Menjumlahkan penyebut', 'Menjumlahkan atau mengurangkan pembilang dan penyebut sekaligus pada operasi pecahan.', 'Pada beberapa soal operasi pecahan, pilihan jawaban menunjukkan bahwa penyebut ikut dijumlahkan. Langkah menyamakan penyebut masih perlu dilatih.') on conflict (id) do update set label = excluded.label, description = excluded.description, insight = excluded.insight;
insert into public.misconceptions (id, label, description, insight) values ('m-keliling-luas-tertukar', 'Keliling dan luas tertukar', 'Menggunakan rumus luas ketika diminta keliling, atau sebaliknya.', 'Pada beberapa soal bangun datar, pilihan jawaban menunjukkan bahwa keliling dan luas masih tertukar. Membedakan keduanya perlu diperkuat.') on conflict (id) do update set label = excluded.label, description = excluded.description, insight = excluded.insight;
insert into public.misconceptions (id, label, description, insight) values ('m-luas-segitiga-tanpa-setengah', 'Luas segitiga tanpa dibagi dua', 'Menghitung luas segitiga dengan alas × tinggi tanpa dibagi dua.', 'Pada soal luas segitiga, pilihan jawaban menunjukkan bahwa hasil alas × tinggi belum dibagi dua.') on conflict (id) do update set label = excluded.label, description = excluded.description, insight = excluded.insight;
insert into public.misconceptions (id, label, description, insight) values ('m-volume-jumlah-rusuk', 'Volume dijumlahkan, bukan dikalikan', 'Menjumlahkan panjang rusuk untuk menghitung volume.', 'Pada soal volume, pilihan jawaban menunjukkan bahwa ukuran bangun masih dijumlahkan, belum dikalikan.') on conflict (id) do update set label = excluded.label, description = excluded.description, insight = excluded.insight;
insert into public.misconceptions (id, label, description, insight) values ('m-rata-rata-tanpa-bagi', 'Rata-rata tanpa dibagi banyak data', 'Menjumlahkan seluruh data tanpa membaginya dengan banyak data.', 'Pada soal rata-rata, pilihan jawaban menunjukkan bahwa jumlah data belum dibagi dengan banyaknya data.') on conflict (id) do update set label = excluded.label, description = excluded.description, insight = excluded.insight;
